CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS plans(id text PRIMARY KEY, title text NOT NULL, price_cents integer NOT NULL DEFAULT 0, max_branches integer NOT NULL, max_staff integer NOT NULL, trial_days integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
INSERT INTO plans(id,title,price_cents,max_branches,max_staff,trial_days) VALUES ('free','Free',0,1,2,0),('basic','Basic',149900,2,10,14),('premium','Premium',399900,50,500,14) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('owner','manager','cashier','staff')), active boolean NOT NULL DEFAULT true, UNIQUE(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL UNIQUE REFERENCES tenants(id), plan_id text NOT NULL REFERENCES plans(id), status text NOT NULL CHECK(status IN ('trial','active','past_due','expired','cancelled')), trial_ends_at timestamptz, current_period_ends_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS password_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), email text NOT NULL, role text NOT NULL CHECK(role IN ('manager','cashier','staff')), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, address text NOT NULL DEFAULT '', open_time time DEFAULT '07:00', close_time time DEFAULT '21:00', active boolean DEFAULT true, created_at timestamptz DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, UNIQUE(tenant_id,id), UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), category_id uuid, name text NOT NULL, description text DEFAULT '', price_cents integer NOT NULL CHECK(price_cents>=0), cost_cents integer NOT NULL DEFAULT 0 CHECK(cost_cents>=0), image_url text, active boolean NOT NULL DEFAULT true, created_at timestamptz DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,category_id) REFERENCES categories(tenant_id,id));
CREATE TABLE IF NOT EXISTS variations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), product_id uuid NOT NULL, name text NOT NULL, price_delta_cents integer NOT NULL DEFAULT 0, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS addons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, price_cents integer NOT NULL CHECK(price_cents>=0), active boolean NOT NULL DEFAULT true, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS ingredients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, unit text NOT NULL DEFAULT 'g', quantity numeric(14,3) NOT NULL DEFAULT 0 CHECK(quantity>=0), low_stock_at numeric(14,3) NOT NULL DEFAULT 0, unit_cost_cents integer NOT NULL DEFAULT 0, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS recipes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), product_id uuid NOT NULL, ingredient_id uuid NOT NULL, quantity numeric(14,3) NOT NULL CHECK(quantity>0), UNIQUE(tenant_id,product_id,ingredient_id), FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,ingredient_id) REFERENCES ingredients(tenant_id,id));
CREATE TABLE IF NOT EXISTS suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, contact text DEFAULT '', UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), ingredient_id uuid NOT NULL, branch_id uuid, delta numeric(14,3) NOT NULL, reason text NOT NULL, reference_id uuid, created_at timestamptz DEFAULT now(), FOREIGN KEY(tenant_id,ingredient_id) REFERENCES ingredients(tenant_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE IF NOT EXISTS tables(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), branch_id uuid NOT NULL, label text NOT NULL, seats integer DEFAULT 2, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE IF NOT EXISTS promotions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), code text NOT NULL, kind text NOT NULL CHECK(kind IN ('percent','fixed')), value integer NOT NULL CHECK(value>=0), active boolean DEFAULT true, expires_at timestamptz, UNIQUE(tenant_id,code), UNIQUE(tenant_id,id));
CREATE SEQUENCE IF NOT EXISTS order_number_seq;
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), branch_id uuid NOT NULL, cashier_id uuid NOT NULL REFERENCES users(id), order_number bigint NOT NULL DEFAULT nextval('order_number_seq'), order_type text NOT NULL CHECK(order_type IN ('dine_in','takeout','delivery')), table_id uuid, status text NOT NULL DEFAULT 'paid' CHECK(status IN ('paid','refunded')), subtotal_cents integer NOT NULL, discount_cents integer NOT NULL DEFAULT 0, tax_cents integer NOT NULL DEFAULT 0, service_cents integer NOT NULL DEFAULT 0, total_cents integer NOT NULL, payment_method text NOT NULL CHECK(payment_method IN ('cash','gcash','maya','card')), amount_tendered_cents integer, change_cents integer DEFAULT 0, promo_code text, created_at timestamptz DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id), FOREIGN KEY(tenant_id,table_id) REFERENCES tables(tenant_id,id));
CREATE TABLE IF NOT EXISTS order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), order_id uuid NOT NULL, product_id uuid NOT NULL, product_name text NOT NULL, variation_name text, addons jsonb NOT NULL DEFAULT '[]', quantity integer NOT NULL CHECK(quantity>0), unit_price_cents integer NOT NULL, total_cents integer NOT NULL, FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id), FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id));
CREATE TABLE IF NOT EXISTS expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), branch_id uuid, title text NOT NULL, amount_cents integer NOT NULL CHECK(amount_cents>=0), spent_on date NOT NULL DEFAULT current_date, FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE IF NOT EXISTS attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), user_id uuid NOT NULL REFERENCES users(id), branch_id uuid, clock_in timestamptz NOT NULL DEFAULT now(), clock_out timestamptz, FOREIGN KEY(tenant_id,branch_id) REFERENCES branches(tenant_id,id));
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), user_id uuid REFERENCES users(id), action text NOT NULL, details jsonb DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS shop_settings(tenant_id uuid PRIMARY KEY REFERENCES tenants(id), tax_basis_points integer NOT NULL DEFAULT 0, service_basis_points integer NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'PHP', receipt_footer text NOT NULL DEFAULT 'Thank you!');
CREATE INDEX IF NOT EXISTS orders_tenant_date_idx ON orders(tenant_id,created_at DESC);
CREATE INDEX IF NOT EXISTS order_items_order_idx ON order_items(tenant_id,order_id);
CREATE INDEX IF NOT EXISTS stock_movements_tenant_date_idx ON stock_movements(tenant_id,created_at DESC);
-- RLS provides a second, database-enforced protection boundary for all workspace data.
DO $$ DECLARE tab text; BEGIN
  FOREACH tab IN ARRAY ARRAY['memberships','subscriptions','invites','branches','categories','products','variations','addons','ingredients','recipes','suppliers','stock_movements','tables','promotions','orders','order_items','expenses','attendance','audit_logs','shop_settings'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tab);
    EXECUTE format('DROP POLICY IF EXISTS tenant_scope ON %I',tab);
    EXECUTE format('CREATE POLICY tenant_scope ON %I USING (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id = nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',tab);
  END LOOP;
END $$;
-- App database role cannot bypass RLS. Migration owner must differ from APP_DB_USER for strict production enforcement.

-- Resolve a cryptographically random invitation token's workspace before enabling tenant RLS.
-- In production, grant EXECUTE only to your non-owner API database role.
CREATE OR REPLACE FUNCTION public.invitation_tenant(p_hash text) RETURNS uuid
LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$
 SELECT tenant_id FROM public.invites WHERE token_hash=p_hash AND accepted_at IS NULL AND expires_at>now() LIMIT 1;
$$;
